import time, os, glob
from datetime import datetime

NUM_CORES = int(os.popen('nproc').read().strip())

def loadavg():
    p = open('/proc/loadavg').read().split()
    return float(p[0]), float(p[1]), float(p[2])

def cpu_pct():
    def stat():
        v = list(map(int, open('/proc/stat').readline().split()[1:]))
        return v[3], sum(v)
    i1,t1=stat(); time.sleep(0.5); i2,t2=stat()
    dt=t2-t1; return round(100*(1-(i2-i1)/dt),1) if dt else 0

def mem():
    d={}
    for l in open('/proc/meminfo'):
        k,v=l.split(':',1); d[k.strip()]=int(v.strip().split()[0])
    tot=d.get('MemTotal',0); av=d.get('MemAvailable',0)
    used=tot-av; return used//1024,tot//1024,round(100*used/tot,1) if tot else 0

def bar(p,w=20):
    f=int(w*p/100); return '['+'#'*f+'-'*(w-f)+f'] {p:5.1f}%'

def temps():
    t={}
    for z in sorted(glob.glob('/sys/class/thermal/thermal_zone*/temp')):
        try: t[z.split('/')[4]]=round(int(open(z).read())/1000,1)
        except: pass
    return t

print('='*58)
print(f'  Live Monitor | {NUM_CORES} cores | stress running')
print('='*58)
for i in range(5):
    la1,la5,la15=loadavg()
    cp=cpu_pct()
    mu,mt,mp=mem()
    ts=temps()
    now=datetime.now().strftime('%H:%M:%S')
    print(f'\\n  [{now}] Sample {i+1}/5')
    print(f'  Load  : {la1:.2f} / {la5:.2f} / {la15:.2f}  (1m/5m/15m, {NUM_CORES} cores)')
    print(f'  CPU   : {bar(cp)}')
    print(f'  Mem   : {bar(mp)}  {mu}/{mt} MB')
    if ts:
        for n,v in list(ts.items())[:4]: print(f'  Temp  : {n}: {v} C')
    else:
        print('  Temp  : No thermal sensors (container/VM)')
    if i<4: time.sleep(2)
print('\\n' + '='*58)
